import icontract


def is_space_comma_dot(c: str) -> bool:
    return c == ' ' or c == ',' or c == '.'


@icontract.ensure(lambda s, result: len(result) == len(s))
@icontract.ensure(lambda s, result: all(
    (result[i] == ':') if is_space_comma_dot(s[i]) else (result[i] == s[i]) for i in range(len(s))))
def replaceWithColon(s: str) -> str:
    out = []
    for c in s:
        if is_space_comma_dot(c):
            out.append(':')
        else:
            out.append(c)
    return ''.join(out)
